import subprocess


def available(cmd):
    try:
        r = subprocess.run([cmd, '--version'], capture_output=True)
    except FileNotFoundError:
        return False
    return r.returncode == 0


if not available('gcc'):
    print('NOGCC')
elif not available('make'):
    print('NOMAKE')
else:
    print('GCC OK')

